SELECT 'GaAs' AS material, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year FROM data
UNION ALL SELECT 'InAs' AS material, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year FROM data1
UNION ALL SELECT 'AlAs' AS material, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year FROM data2
UNION ALL SELECT 'InP' AS material, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year FROM data3